const now = new Date();
let year, month;
const dayOfMonth = now.getDate();
if (dayOfMonth === 5) {
  const prevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  year = prevMonth.getFullYear();
  month = prevMonth.getMonth() + 1;
} else {
  year = now.getFullYear();
  month = now.getMonth() + 1;
}
const period = `${year}-${String(month).padStart(2, '0')}`;
const periodStart = `${period}-01`;
const lastDay = new Date(year, month, 0).getDate();
const periodEnd = `${period}-${String(lastDay).padStart(2, '0')}`;
return [{json: {period, year, month, periodStart, periodEnd, generatedAt: now.toISOString()}}];

const periodData = $('Determine JPK Period').first().json;
const clients = $input.all();
return clients.map(c => ({json: {...c.json, ...periodData}}));

const invoices = $input.all();
const clientData = $('Per Client').first().json;
const results = [];

for (const item of invoices) {
  const inv = item.json;
  let jpk_marker = inv.jpk_marker || 'DI';
  let marker_reason = '';

  if (inv.ksef_number && inv.ksef_number.trim() !== '') {
    jpk_marker = 'NrKSeF';
    marker_reason = `KSeF number: ${inv.ksef_number}`;
  } else if (!inv.ksef_number && inv.jpk_marker === 'OFF') {
    jpk_marker = 'OFF';
    marker_reason = 'Offline invoice, uploaded within deadline';
  } else if (!inv.ksef_number && inv.jpk_marker === 'BFK') {
    jpk_marker = 'BFK';
    marker_reason = 'Offline invoice, uploaded late - correction needed';
  } else {
    jpk_marker = 'DI';
    marker_reason = 'Cannot determine - manual review required';
  }

  results.push({json: {...inv, jpk_marker, marker_reason, client_name: clientData.client_name, period: clientData.period, is_NrKSeF: jpk_marker === 'NrKSeF' ? 'TAK' : '', is_OFF: jpk_marker === 'OFF' ? 'TAK' : '', is_BFK: jpk_marker === 'BFK' ? 'TAK' : '', is_DI: jpk_marker === 'DI' ? 'TAK' : ''}});
}
return results;

const invoices = $input.all();
const csvHeader = 'Numer_faktury;Data;NIP_kontrahenta;Kwota_netto;Kwota_VAT;Kwota_brutto;NrKSeF;OFF;BFK;DI;Numer_KSeF;Uwagi';
const csvRows = invoices.map(item => {
  const inv = item.json;
  const contractorNip = inv.direction === 'sales' ? (inv.buyer_nip || '') : (inv.seller_nip || '');
  return [inv.invoice_number || '', inv.issue_date || '', contractorNip, Number(inv.net_amount || 0).toFixed(2), Number(inv.vat_amount || 0).toFixed(2), Number(inv.gross_amount || 0).toFixed(2), inv.is_NrKSeF, inv.is_OFF, inv.is_BFK, inv.is_DI, inv.ksef_number || '', `"${inv.marker_reason}"`].join(';');
});
const csvContent = [csvHeader, ...csvRows].join('\n');
const client = invoices[0]?.json || {};
const filename = `JPK_VAT_${client.client_nip}_${client.period}.csv`;
return [{json: {csvContent, filename, client_nip: client.client_nip, client_name: client.client_name, period: client.period, invoiceCount: invoices.length, invoices: invoices.map(i => i.json)}}];

const data = $input.first().json;
const invoices = data.invoices || [];
const stats = {total: invoices.length, nrksef: invoices.filter(i => i.jpk_marker === 'NrKSeF').length, off: invoices.filter(i => i.jpk_marker === 'OFF').length, bfk: invoices.filter(i => i.jpk_marker === 'BFK').length, di: invoices.filter(i => i.jpk_marker === 'DI').length};
const totalNet = invoices.reduce((s, i) => s + (parseFloat(i.net_amount) || 0), 0);
const totalVat = invoices.reduce((s, i) => s + (parseFloat(i.vat_amount) || 0), 0);
const totalGross = invoices.reduce((s, i) => s + (parseFloat(i.gross_amount) || 0), 0);
return [{json: {...data, stats, financials: {totalNet: totalNet.toFixed(2), totalVat: totalVat.toFixed(2), totalGross: totalGross.toFixed(2)}, hasWarnings: stats.bfk > 0 || stats.di > 0, warningMessage: stats.bfk > 0 ? `${stats.bfk} faktur z BFK wymaga korekty!` : (stats.di > 0 ? `${stats.di} faktur wymaga weryfikacji (DI)` : '')}}];

const data = $('Calculate Summary Stats').first().json;
const { stats, financials, client_nip, client_name, period, warningMessage, filename } = data;
const warningHtml = warningMessage ? `<tr><td colspan="2" style="background:#fff3cd;color:#856404;padding:12px;border:1px solid #ffc107;font-weight:bold;">UWAGA: ${warningMessage}</td></tr>` : '';
const emailBody = `<html><body style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;">
<div style="background:#1a5276;color:white;padding:20px;"><h1 style="margin:0;font-size:22px;">JPK_VAT - ${period}</h1><p style="margin:5px 0 0;opacity:0.9;">${client_name} (NIP: ${client_nip})</p></div>
<div style="padding:20px;border:1px solid #ddd;">
<table style="width:100%;border-collapse:collapse;">${warningHtml}
<tr style="background:#f8f9fa;"><td style="padding:8px;border:1px solid #ddd;">Lacznie</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${stats.total}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;">NrKSeF</td><td style="padding:8px;border:1px solid #ddd;text-align:right;color:#28a745;">${stats.nrksef}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;">OFF</td><td style="padding:8px;border:1px solid #ddd;text-align:right;color:#17a2b8;">${stats.off}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;">BFK</td><td style="padding:8px;border:1px solid #ddd;text-align:right;color:#dc3545;">${stats.bfk}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;">DI</td><td style="padding:8px;border:1px solid #ddd;text-align:right;color:#ffc107;">${stats.di}</td></tr>
</table>
<p>Netto: ${financials.totalNet} PLN | VAT: ${financials.totalVat} PLN | Brutto: ${financials.totalGross} PLN</p>
<p style="color:#666;font-size:12px;">Zalacznik: ${filename}</p>
</div></body></html>`;
return [{json: {...data, emailBody, emailSubject: `JPK_VAT ${period} - ${client_name} (${stats.total} faktur)`}}];

